/* 108E:0286  fill page 0 with one tile (background for text pages) */
void ui_text_page(int tile)
{
    int di, si;
    port_picture = -1;                   /* (port) */
    ega_outw(0x3C4, 0x0F02);
    WRITE_MODE_LATCH();
    set_draw_page(0);
    set_display_page(0);
    for (di = 0; di < 0x19; di++)
        for (si = 0; si < 0x14; si++) blit_tile((uint16_t)tile, (uint16_t)((si << 1) + di * 0x280));
}

