/* ------------------------------------------------------------------
 * Episodes 2 and 3 (DN2.EXE / DN3.EXE) are the same program with different
 * text.  Where a routine there draws a different number of lines, or at
 * other rows, it is given here as {offset in that episode's data, row}
 * lists, read from the episode's own code (see tools/episode_map.py). */
typedef struct { uint16_t off; uint8_t row; } EpLine;
static void ep_lines(const EpLine *l, int n, int x)
{
    int i;
    for (i = 0; i < n; i++) ui_text(ds_ep_str(l[i].off), x, l[i].row);
}
#define EP_LINES(tab, x) ep_lines(tab, (int)(sizeof tab / sizeof tab[0]), x)

