/* 108E:3D1E  "quit?" -> 1 if Y */
/* (port) UI_CTX_YESNO: a controller's confirm button answers Y, back answers N */
int dlg_confirm_quit(int x) { int c = ui_context; ui_context = UI_CTX_YESNO; dlg_confirm_quit_v(x); ui_context = c; return last_scancode == 0x15; }
int ui_confirm_quit(int x)  { return dlg_confirm_quit(x); }
/* 108E:14E6  "restart level?" (caller tests last_scancode for Y) */
int ui_confirm_restart(void) { int c = ui_context; ui_context = UI_CTX_YESNO; ui_confirm_restart_v(); ui_context = c; return last_scancode == 0x15; }
